import{z as s,x as R,o as r,c as p,q as t,j as E,D as e,d as o,s as n,S as i}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"RLVR","description":"","frontmatter":{"title":"RLVR","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rlvr.md","filePath":"llm/rlvr.md","lastUpdated":1791413859000}'),A={name:"llm/rlvr.md"};function B(d,a,h,m,P,u){const l=R("Mermaid");return r(),p("div",null,[a[2]||(a[2]=t('<h1 id="rlvr" tabindex="-1">RLVR <a class="header-anchor" href="#rlvr" aria-label="Permalink to &quot;RLVR&quot;">​</a></h1><div class="epigraph"><p>把奖励模型换成验证函数：只有生成被判定为可核实时才给常数奖励，否则为零；目标仍是带 KL 的强化学习，只是标量来自程序而不是神经网络。</p><footer>—— Lambert 等，Tülu 3: Pushing Frontiers in Open Language Model Post-Training，arXiv:2411.15124</footer></div><p><a href="/llm/tulu">Tulu 3</a> 专文写整条开放后训练配方。<strong>RLVR</strong>（Reinforcement Learning with Verifiable Rewards）是其中第四段被单独命名的方法：在数学与可检查指令上，用确定性验证器给出稀疏标量，再用 <a href="/llm/schulman-ppo">PPO</a> 优化。它比 R1 早公开成「配方级」术语，也不绑定 <a href="/llm/grpo">GRPO</a>。本篇写验证器奖励本身、与结果监督 RL 的异同，以及 Tulu 3 里已经测到的过优化。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RLHF 的 RM 在开放写作上有用，对 GSM8K / MATH 的对错分辨很弱：文风像教师也能拿高分，算错仍过。过程标注与 PRM 又贵。若任务存在<strong>程序真值</strong>——最终数字、代码测试、<a href="/llm/ifeval">IFEval</a> 式约束——奖励不必学，可以算。需要一种把「可验证技能」从偏好阶段拆出来的后训练，使数学与格式约束进入梯度，同时不要求实验室再训与策略同规模的 RM。</p><p><span class="marginnote">验证器就是一个判对错的小程序：喂给它题目和模型的回答，它输出「过 / 不过」。因为对错由代码判定而不是神经网络打分，奖励既便宜又稳定——代价是只能覆盖答案能被程序检查的题型，开放写作没有这种真值。</span></p><p>命名上的混乱来自时间线。Lambert 等人在 2024 年 11 月把 RLVR 写成 Tulu 3 的最后一段；2025 年 R1 用规则奖励 + GRPO 做大规模推理，社区常把两者口语化成同一件事。精确说法：RLVR 是<strong>奖励来源</strong>（验证器 vs RM）；GRPO 是<strong>优势估计</strong>。Tulu 3 的 RLVR 实现是 PPO + 价值头，价值从通用 RM 初始化。它也不是新的学习理论：作者自己把它写成对 STaR / ReST-EM 与「执行反馈 RL」的简化——不做逐步搜索，只把匹配或约束谓词当成二元信号。新意在开放配方里把这一段接在 SFT 与 DPO 之后，并配上可下载的验证器与去污染评测。</p><h3 id="验证器覆盖什么" tabindex="-1">验证器覆盖什么 <a class="header-anchor" href="#验证器覆盖什么" aria-label="Permalink to &quot;验证器覆盖什么&quot;">​</a></h3><p>Tulu 3 公开三类提示与验证：GSM8K、MATH、以及可检查约束（从 IFEval 的 25 类约束合成）。奖励在成功时为常数 \\(\\alpha\\)（实验取 <strong>10</strong>），否则 0，再减 \\(\\beta\\,\\mathrm{KL}(\\pi_\\theta\\|\\pi_{\\mathrm{ref}})\\)。他们<strong>没有</strong>把代码执行反馈写进主 RLVR 段，尽管讨论里指向 Gehring 等人的执行 RL。更复杂的形式化证明器、含糊的开放写作，没有 \\(v(x,y)\\)。</p><p><span class="marginnote">数据在 Hugging Face：<code>allenai/RLVR-GSM</code>、<code>RLVR-MATH</code>、<code>RLVR-IFeval</code> 与混合集。复现应对验证脚本，而不是只下载提示。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>目标（原文式 (7)）为</p> \\[\\max_{\\pi_\\theta}\\mathbb{E}_{y\\sim\\pi_\\theta(\\cdot\\mid x)}\\bigl[v(x,y)-\\beta\\,\\mathrm{KL}[\\pi_\\theta(\\cdot\\mid x)\\,\\|\\,\\pi_{\\mathrm{ref}}(\\cdot\\mid x)]\\bigr], \\]<p>\\(v\\in\\{0,\\alpha\\}\\)。优化器用 PPO。超参与「对 RM 做 PPO」不同：最终 8B 取 \\(\\beta=0.05\\)、\\(\\omega=0.0\\)；70B 取 \\(\\beta=0.07\\)、\\(\\omega=0.07\\)（\\(\\omega\\) 为原文表中与 RM 设定对照的项）。价值头从通用 RM 初始化，比其它初始化在 GSM8K 上更好。从 <strong>DPO 检查点</strong>接 RLVR，比从较弱 SFT 接，在同一 \\(\\beta\\) 下 KL 更小。提示可多 epoch，约 10 万 / 7473 ≈ 13 epoch 量级的消融，epoch 间打乱。异步 PPO：vLLM 推理与 ZeRO-3 学习器分开，规模到 405B。</p><p><span class="marginnote">「稀疏奖励」指模型一次生成几百个 token，最后只收到一个比特量级的信号（\\(\\alpha\\) 或 0）。好比考完整张试卷只知道总分、不知道哪步扣分，学习只能靠大量重复采样把「对的走法」平均出来——这也是为什么这里要用 PPO 而不是一次反向传播。</span></p><p>技能结果（以报告表为准）：RLVR 相对 DPO 抬 GSM8K / MATH / IFEval 等目标域；<strong>总平均不保证升</strong>。下游曲线在 KL 变大后会掉——即使用真值验证器，也会过优化（IFEval 上尤其明显）。把验证器分<strong>加在 RM 分数上</strong>的消融，不如纯验证器。最终应在开发评测上按步选检查点，而不是训到奖励平台。</p>',16)),(r(),E(i,null,{default:e(()=>[n(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%8F%90%E7%A4%BA%20x%22%5D%20--%3E%20PI%5B%22%E7%AD%96%E7%95%A5%E9%87%87%E6%A0%B7%20y%22%5D%0A%20%20PI%20--%3E%20V%5B%22%E9%AA%8C%E8%AF%81%E5%99%A8%20v(x%2Cy)%20%E2%88%88%20%7B0%2C%20%CE%B1%7D%22%5D%0A%20%20V%20--%3E%20PPO%5B%22PPO%20%2B%20%E4%BB%B7%E5%80%BC%E5%A4%B4%22%5D%0A%20%20REF%5B%22%CF%80_ref%22%5D%20--%3E%20KL%5B%22%CE%B2%20KL%22%5D%0A%20%20KL%20--%3E%20PPO%0A%20%20RM%5B%22%E9%80%9A%E7%94%A8%20RM%20%E5%8F%AA%E5%88%9D%E5%A7%8B%E5%8C%96%20V%22%5D%20--%3E%20PPO%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h3 id="与-r1-规则奖励同构-栈不同" tabindex="-1">与 R1 规则奖励同构，栈不同 <a class="header-anchor" href="#与-r1-规则奖励同构-栈不同" aria-label="Permalink to &quot;与 R1 规则奖励同构，栈不同&quot;">​</a></h3><p>两者都是结果监督：中间步骤不打分，假推理只要终点过检查器就能得正奖励。差别：Tulu 3 强调 KL 锚与价值函数，规模从 8B 到 405B 的<strong>开放配方</strong>；R1-Zero 去掉 SFT、用 GRPO、KL 很小并周期性换参考，追求长链涌现。RLVR 不是「小规模 R1」，R1 也不是「大规模 Tulu 3」。引用时分开：<a href="/llm/deepseek-r1-paper">R1 论文</a> 的超参表与 Lambert 的 \\(\\alpha=10\\) 不能混抄。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>验证器把信用钉在可判定命题上。GSM8K 的 \\(v\\) 是答案匹配；IFEval 的 \\(v\\) 是约束谓词（恰好三段、禁止大写等）。策略提高的是「让验证器返回真」的生成程序，包括格式。稀疏性与 RL 相同：整段一个比特量级的信息，样本效率低于逐步 PRM，但零标注成本。</p>',4)),(r(),E(i,null,{default:e(()=>[n(l,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E6%A8%A1%E5%9E%8B%E7%94%9F%E6%88%90%E4%B8%80%E6%9D%A1%E5%9B%9E%E7%AD%94%22%5D%20--%3E%20B%7B%22%E9%AA%8C%E8%AF%81%E5%99%A8%20v(x%2Cy)%22%7D%0A%20%20B%20--%20%22%E9%80%9A%E8%BF%87%EF%BC%8C%E5%A5%96%E5%8A%B1%20%CE%B1%22%20--%3E%20C%5B%22%E5%BC%BA%E5%8C%96%E8%BF%99%E6%9D%A1%E7%94%9F%E6%88%90%E8%B7%AF%E5%BE%84%22%5D%0A%20%20B%20--%20%22%E4%B8%8D%E9%80%9A%E8%BF%87%EF%BC%8C%E5%A5%96%E5%8A%B1%200%22%20--%3E%20D%5B%22%E6%8A%91%E5%88%B6%E8%BF%99%E6%9D%A1%E7%94%9F%E6%88%90%E8%B7%AF%E5%BE%84%22%5D%0A%20%20C%20--%3E%20E%5B%22%E7%9B%AE%E6%A0%87%E5%9F%9F%E5%88%86%E6%95%B0%E4%B8%8A%E6%B6%A8%22%5D%0A%20%20E%20--%3E%20F%5B%22%E5%AD%A6%E4%BC%9A%E9%92%BB%E9%AA%8C%E8%AF%81%E5%99%A8%E7%9A%84%E6%A0%BC%E5%BC%8F%E7%A9%BA%E5%AD%90%22%5D%0A%20%20F%20--%3E%20G%5B%22KL%20%E5%8F%98%E5%A4%A7%EF%BC%8C%E8%81%8A%E5%A4%A9%E4%B8%8E%E5%AE%89%E5%85%A8%E5%88%86%E4%B8%8B%E6%BB%91%22%5D%0A%20%20G%20--%3E%20H%5B%22%E9%A1%BB%E5%9C%A8%E5%BC%80%E5%8F%91%E8%AF%84%E6%B5%8B%E4%B8%8A%E6%97%A9%E5%81%9C%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>保留 KL 是因为 Tulu 的产品目标是<strong>多技能助手</strong>：数学 RL 不得把聊天与安全轴撕掉。\\(\\beta\\) 过小，目标域分还在涨，平均分已掉——过优化的对象可以是「验证器可黑客的格式」，而不必是学坏的 RM。这解释了为何真值奖励仍要早停。基础设施上他们把推理放到独立 GPU 的 vLLM，学习器走 ZeRO-3，才能把带价值头的 PPO 拉到 405B；这与后来开源推理社区默认的「无 critic、组采样」不是同一套机器账。读 RLVR 的 405B 数字，要连这三项模型（策略、参考、价值）一起算显存，不能只按 GRPO 的两份对数概率去外推墙钟。价值头从通用 RM 初始化有效，说明即使标量来自验证器，advantage 的逐步结构仍受益于偏好模型里已经学到的「什么样的回复完整」。</p><p><span class="marginnote">初学者容易以为「奖励来自标准答案就不会跑偏」。实际上模型会先学会钻格式空子——比如把答案硬凑成验证器能解析的写法——目标分还在涨，别的能力已经掉了。所以即便奖励百分百正确，也要盯着开发评测选检查点，而不是训到奖励平台为止。</span></p><p><span class="marginnote">\\(\\alpha=10\\) 只来自试点，作者未再扫。换 0/1 或 \\(\\pm 1\\)（DAPO）会改与 KL 的相对尺度，必须重调 \\(\\beta\\)。不要把 10 当成验证器 RL 的物理常数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>RLVR 不覆盖开放写作；那是 Tulu 的 DPO 段。验证器写错（解析失败、约束实现与 IFEval 不一致）会系统性强化错误程序。MATH 的等价判断比整数 GSM8K 脆，假阴性把对的当 0。405B 实验证明配方可放大，不证明每个实验室都该上价值头——后续开源推理栈更多用 GRPO 类无 critic。</p><p>社区把任何规则奖励都叫 RLVR，会抹掉 Tulu 的评测协议（开发/留出、去污染）。写「我们做了 RLVR」应注明验证器定义、\\(\\alpha\\)、算法（PPO 还是 GRPO）与是否保留 RM。</p><p><span class="marginnote">STaR / ReST-EM 也用对错过滤再监督学习。RLVR 的差分是在线策略梯度而不是离线模仿被滤后的正例。二者可叠，但论文把它写成 PPO 段。</span></p><h3 id="何时不必单开-rlvr-段" tabindex="-1">何时不必单开 RLVR 段 <a class="header-anchor" href="#何时不必单开-rlvr-段" aria-label="Permalink to &quot;何时不必单开 RLVR 段&quot;">​</a></h3><p>没有可靠 \\(v\\)，不要用随机启发式冒充验证器。已经在用 R1 式大规模 GRPO，再套 Tulu 的 \\(\\alpha=10\\) PPO 是另一套超参。只要格式约束、数据少，SFT 加拒绝采样可能够。要逐步监督，看 <a href="/llm/verify-step">Lightman</a>，不是把 PRM 改名为 RLVR。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RLVR 用程序验证器替换奖励模型，成功给常数 \\(\\alpha\\)、否则 0，再 KL 约束下做 RL。</li><li>Tulu 3 用 PPO、价值头从通用 RM 初始化，主攻 GSM8K / MATH / IFEval；从 DPO 检查点接更稳。</li><li>目标域会升，总平均与 OOD 不保证；真值奖励仍会过优化，需选检查点。</li><li>奖励来源 ≠ 优势估计：RLVR 可配 PPO 或 GRPO；R1 是后者加规则奖励。</li><li>出处：Lambert 等，<em>Tülu 3</em>，arXiv:2411.15124；代码 <code>allenai/open-instruct</code>。</li></ul>',11))])}const g=s(A,[["render",B]]);export{c as __pageData,g as default};
